from math import sqrt

def is_prime(n):
    """Helper function to check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a < 2:
        return False
    prime_factors = 0
    for i in range(2, int(sqrt(a)) + 1):
        if a % i == 0:
            if is_prime(i):
                prime_factors += 1
            if is_prime(a // i):
                prime_factors += 1
            if prime_factors > 3:
                return False
            if a % i == 0 and a // i == i:
                prime_factors -= 1
    return prime_factors == 3
